"""Price calculation with tiered discounts."""

from decimal import ROUND_HALF_UP, Decimal
from enum import Enum

BASE_MARKUP = Decimal("1.35")
CURRENCY = "EUR"
CENTS = Decimal("0.01")


class Tier(str, Enum):
    """Customer pricing tiers."""

    RETAIL = "retail"
    TRADE = "trade"
    WHOLESALE = "wholesale"


DISCOUNTS = {
    Tier.RETAIL: Decimal("0.00"),
    Tier.TRADE: Decimal("0.10"),
    Tier.WHOLESALE: Decimal("0.22"),
}


class PriceBook:
    """Cost prices keyed by SKU, plus the rules that turn them into quotes."""

    def __init__(self, costs: dict[str, Decimal]) -> None:
        """Hold a copy of the cost table so callers cannot mutate it later."""
        self._costs: dict[str, Decimal] = {}
        for sku, cost in costs.items():
            if cost < 0:
                message = f"negative cost price for {sku}"
                raise ValueError(message)
            self._costs[sku] = Decimal(cost)

    def cost_of(self, sku: str) -> Decimal:
        """Return the cost price for a SKU."""
        try:
            return self._costs[sku]
        except KeyError as exc:
            message = f"no cost price recorded for {sku}"
            raise LookupError(message) from exc

    def quote(self, sku: str, tier: Tier, quantity: int = 1) -> Decimal:
        """Quote a line total for a SKU at a tier."""
        if quantity < 1:
            message = "quantity must be at least one"
            raise ValueError(message)
        unit = self.cost_of(sku) * BASE_MARKUP
        # Discounts apply to the marked-up price, not the cost price.
        discount = DISCOUNTS[tier]
        discounted = unit * (Decimal("1.00") - discount)
        line_total = discounted * quantity
        return line_total.quantize(CENTS, rounding=ROUND_HALF_UP)

    def price_list(self, tier: Tier) -> list[tuple[str, Decimal]]:
        """Return every SKU with its unit price at a tier, SKU order."""
        rows: list[tuple[str, Decimal]] = []
        for sku in sorted(self._costs):
            rows.append((sku, self.quote(sku, tier)))
        return rows

    def cheapest(self, tier: Tier) -> str:
        """Return the SKU with the lowest unit price at a tier."""
        rows = self.price_list(tier)
        if not rows:
            message = "price book is empty"
            raise LookupError(message)
        best_sku, best_price = rows[0]
        for sku, price in rows[1:]:
            if price < best_price:
                best_sku, best_price = sku, price
        return best_sku


def format_money(amount: Decimal) -> str:
    """Render an amount with the configured currency suffix."""
    quantized = amount.quantize(CENTS, rounding=ROUND_HALF_UP)
    return f"{quantized} {CURRENCY}"

/**
 * Inventory tracking for a small warehouse.
 */

import { PriceBook, Tier } from "./pricing";
import type { Money } from "./types";

export const MAX_ITEMS = 500;
export const DEFAULT_WAREHOUSE = "main";

// Reorder thresholds are per-category because bolts and lathes do not move
// at remotely the same rate.
export const REORDER_THRESHOLDS: Record<string, number> = {
  fastener: 250,
  tool: 5,
  consumable: 40,
};

export interface Item {
  sku: string;
  category: string;
  quantity: number;
}

export function needsReorder(item: Item): boolean {
  const threshold = REORDER_THRESHOLDS[item.category];
  if (threshold === undefined) {
    // An unknown category is a data error, not a reason to reorder.
    return false;
  }
  if (item.quantity < 0) {
    throw new Error(`${item.sku} has a negative quantity`);
  }
  return item.quantity < threshold;
}

export class Inventory {
  private readonly items: Map<string, Item>;

  private readonly history: string[];

  constructor(public readonly warehouse: string = DEFAULT_WAREHOUSE) {
    if (warehouse.length === 0) {
      throw new Error("warehouse name must not be empty");
    }
    this.items = new Map();
    this.history = [];
  }

  add(item: Item): void {
    if (this.items.size >= MAX_ITEMS) {
      throw new Error(`${this.warehouse} already holds ${MAX_ITEMS} items`);
    }
    const existing = this.items.get(item.sku);
    if (existing !== undefined) {
      this.items.set(item.sku, {
        sku: item.sku,
        category: item.category,
        quantity: existing.quantity + item.quantity,
      });
      this.history.push(`merge ${item.sku}`);
      return;
    }
    this.items.set(item.sku, item);
    this.history.push(`add ${item.sku}`);
  }

  remove(sku: string): Item {
    const item = this.items.get(sku);
    if (item === undefined) {
      // A missing SKU is a caller bug, not an empty result.
      throw new Error(`${sku} is not stocked in ${this.warehouse}`);
    }
    this.items.delete(sku);
    this.history.push(`remove ${sku}`);
    return item;
  }

  reorderList(): Item[] {
    const due: Item[] = [];
    for (const item of this.items.values()) {
      if (needsReorder(item)) {
        due.push(item);
      }
    }
    due.sort((left, right) => left.sku.localeCompare(right.sku));
    return due;
  }

  valueAt(prices: PriceBook, tier: Tier): Money {
    let total = 0;
    for (const item of this.reorderList()) {
      total += prices.quote(item.sku, tier, item.quantity);
    }
    return { amount: total, currency: prices.currency };
  }

  auditTrail(): string[] {
    return this.history.map((entry, index) => {
      const position = String(index + 1).padStart(3, "0");
      return `${position} ${entry}`;
    });
  }
}

/**
 * Price calculation with tiered discounts.
 */

import type { Money } from "./types";

export const BASE_MARKUP = 1.35;
export const CURRENCY = "EUR";

export enum Tier {
  Retail = "retail",
  Trade = "trade",
  Wholesale = "wholesale",
}

const DISCOUNTS: Record<Tier, number> = {
  [Tier.Retail]: 0,
  [Tier.Trade]: 0.1,
  [Tier.Wholesale]: 0.22,
};

export class PriceBook {
  public readonly currency: string = CURRENCY;

  private readonly costs: Map<string, number>;

  constructor(costs: Record<string, number>) {
    // Copy the table so a caller cannot mutate prices behind our back.
    this.costs = new Map();
    for (const [sku, cost] of Object.entries(costs)) {
      if (cost < 0) {
        throw new Error(`negative cost price for ${sku}`);
      }
      this.costs.set(sku, cost);
    }
  }

  costOf(sku: string): number {
    const cost = this.costs.get(sku);
    if (cost === undefined) {
      throw new Error(`no cost price recorded for ${sku}`);
    }
    return cost;
  }

  quote(sku: string, tier: Tier, quantity = 1): number {
    if (quantity < 1) {
      throw new Error("quantity must be at least one");
    }
    const unit = this.costOf(sku) * BASE_MARKUP;
    const discounted = unit * (1 - DISCOUNTS[tier]);
    const lineTotal = discounted * quantity;
    return Math.round(lineTotal * 100) / 100;
  }

  priceList(tier: Tier): Array<[string, number]> {
    const rows: Array<[string, number]> = [];
    for (const sku of [...this.costs.keys()].sort()) {
      rows.push([sku, this.quote(sku, tier)]);
    }
    return rows;
  }

  applyPromotion(sku: string, tier: Tier, promotion: number): number {
    if (promotion < 0 || promotion > 0.5) {
      throw new RangeError(`promotion out of range for ${sku}: ${promotion}`);
    }
    const base = this.quote(sku, tier, 1);
    const promoted = base * (1 - promotion);
    const floorPrice = this.costOf(sku);
    if (promoted < floorPrice) {
      // Never promote below cost: that is a pricing bug, not a deal.
      throw new RangeError(`promotion on ${sku} would sell below cost`);
    }
    return Math.round(promoted * 100) / 100;
  }

  cheapest(tier: Tier): string {
    const rows = this.priceList(tier);
    if (rows.length === 0) {
      throw new Error("price book is empty");
    }
    let [bestSku, bestPrice] = rows[0];
    for (const [sku, price] of rows.slice(1)) {
      if (price < bestPrice) {
        bestSku = sku;
        bestPrice = price;
      }
    }
    return bestSku;
  }
}

export function formatMoney(money: Money): string {
  return `${money.amount.toFixed(2)} ${money.currency}`;
}

/**
 * Reporting helpers that stitch inventory and pricing together.
 */

import { Inventory, Item } from "./inventory";
import { PriceBook, Tier, formatMoney } from "./pricing";
import type { Money } from "./types";

export const REPORT_WIDTH = 72;
export const SEPARATOR = "-".repeat(REPORT_WIDTH);

export class ReportError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ReportError";
  }
}

export function stockValue(inventory: Inventory, prices: PriceBook, tier: Tier): Money {
  let total = 0;
  for (const item of inventory.reorderList()) {
    try {
      total += prices.quote(item.sku, tier, item.quantity);
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : String(cause);
      throw new ReportError(`cannot value ${item.sku}: ${detail}`);
    }
  }
  return { amount: total, currency: prices.currency };
}

export function reorderReport(inventory: Inventory, prices: PriceBook): string {
  const rows = inventory.reorderList();
  if (rows.length === 0) {
    return "nothing to reorder\n";
  }

  const lines = [`reorder report for ${inventory.warehouse}`, SEPARATOR];
  let running = 0;
  for (const item of rows) {
    // Trade pricing is what the purchasing team actually pays.
    const lineTotal = prices.quote(item.sku, Tier.Trade, item.quantity);
    running += lineTotal;
    lines.push(formatRow(item, { amount: lineTotal, currency: prices.currency }));
  }
  lines.push(SEPARATOR);
  lines.push(`total`.padEnd(22) + formatMoney({ amount: running, currency: prices.currency }));
  return `${lines.join("\n")}\n`;
}

function formatRow(item: Item, lineTotal: Money): string {
  const sku = item.sku.padEnd(16);
  const quantity = String(item.quantity).padStart(6);
  const money = formatMoney(lineTotal);
  return `${sku}${quantity}  ${money}`;
}

export function summarise(inventory: Inventory, prices: PriceBook): Record<string, string> {
  const rows = inventory.reorderList();
  const summary: Record<string, string> = {
    warehouse: inventory.warehouse,
    due: String(rows.length),
    value: formatMoney(stockValue(inventory, prices, Tier.Trade)),
  };
  if (rows.length > 0) {
    summary.firstSku = rows[0].sku;
  }
  return summary;
}

/**
 * Shared value types and the guards that police them.
 */

export interface Money {
  amount: number;
  currency: string;
}

export interface Warehouse {
  name: string;
  region: string;
  active: boolean;
}

// Regions the business actually ships to; anything else is a data error.
export const REGIONS = ["eu-west", "eu-central", "uk"] as const;

export type Region = (typeof REGIONS)[number];

export function isRegion(value: string): value is Region {
  return (REGIONS as readonly string[]).includes(value);
}

export function describeWarehouse(warehouse: Warehouse): string {
  const state = warehouse.active ? "active" : "closed";
  const region = isRegion(warehouse.region) ? warehouse.region : "unknown region";
  return `${warehouse.name} (${region}, ${state})`;
}

export function parseWarehouse(payload: unknown): Warehouse {
  if (typeof payload !== "object" || payload === null) {
    throw new TypeError("warehouse payload must be an object");
  }
  const record = payload as Record<string, unknown>;
  const name = record.name;
  const region = record.region;
  const active = record.active;
  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("warehouse name must be a non-empty string");
  }
  if (typeof region !== "string" || !isRegion(region)) {
    throw new TypeError(`unknown warehouse region: ${String(region)}`);
  }
  if (typeof active !== "boolean") {
    throw new TypeError("warehouse active flag must be a boolean");
  }
  return { name, region, active };
}

export function addMoney(left: Money, right: Money): Money {
  if (left.currency !== right.currency) {
    throw new TypeError(`cannot add ${left.currency} to ${right.currency}`);
  }
  return { amount: left.amount + right.amount, currency: left.currency };
}

"""The published product list, priced at a tier."""

from pricing import PriceBook, Tier, format_money

CATALOG_TITLE = "Warehouse catalogue"


def catalogue_lines(prices: PriceBook, tier: Tier) -> list[str]:
    """Render one line per SKU at the given tier."""
    lines = [CATALOG_TITLE]
    for sku, price in prices.price_list(tier):
        lines.append(f"{sku.ljust(16)}{format_money(price)}")
    return lines


def headline_sku(prices: PriceBook, tier: Tier) -> str:
    """The SKU the catalogue leads with."""
    return prices.cheapest(tier)

"""The command surface that drives the modules above."""

from audit import audit_lines
from catalog import catalogue_lines
from customers import Customer
from inventory import Inventory
from orders import raise_order
from pricing import PriceBook, Tier
from warehouse import floor_summary


def run_cli(inventory: Inventory, prices: PriceBook, command: str) -> str:
    """Dispatch one command against the warehouse."""
    if command == "catalogue":
        return "\n".join(catalogue_lines(prices, Tier.TRADE))
    if command == "floor":
        return floor_summary(inventory)
    if command == "order":
        return raise_order(inventory, prices, 1)
    if command == "audit":
        return "\n".join(audit_lines(inventory, prices, Customer("acme")))
    message = f"unknown command {command}"
    raise ValueError(message)

